/**
 * 剧情模块统一日志前缀，便于控制台过滤：输入 Story 过滤。
 */
const PREFIX = '[Story]';

export type StoryLogLevel = 'info' | 'warn' | 'error';

/** 为 true 时输出 storyLogVerboseMsg（高频诊断，默认关） */
export let storyLogVerbose = false;

export function setStoryLogVerbose(enabled: boolean): void {
    storyLogVerbose = enabled;
}

const _onceKeys = new Set<string>();

/** 每个 key 进程内只打一次（适合 AABB 一次性说明等） */
export function storyLogOnce(key: string, level: StoryLogLevel, message: string, context?: Record<string, unknown>): void {
    if (_onceKeys.has(key)) return;
    _onceKeys.add(key);
    storyLog(level, message, context);
}

export function storyLogVerboseMsg(message: string, context?: Record<string, unknown>): void {
    if (!storyLogVerbose) return;
    storyLog('info', message, context);
}

export function storyLog(level: StoryLogLevel, message: string, context?: Record<string, unknown>): void {
    const tail = context && Object.keys(context).length ? ` ${JSON.stringify(context)}` : '';
    const line = `${PREFIX} ${message}${tail}`;
    if (level === 'error') {
        console.error(line);
    } else if (level === 'warn') {
        console.warn(line);
    } else {
        console.log(line);
    }
}
